import { Component, createSignal, For, Setter } from "solid-js";

import { Button } from "#core/ui-next/components/button.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { BoundString } from "#core/ui-next/sandbox/components-browser/components/bound-property.jsx";
import { TextInput } from "#core/ui-next/sandbox/components-browser/components/text-input.jsx";
import { createArraySignal } from "#core/ui-next/utilities/solid-utilities.js";

export const L10nExample: Component = () => {
	const [text, setText] = createSignal("LOC_TRAIT_AKSUM_ABILITY_DESCRIPTION");
	const [args, useArgs] = createArraySignal<string>();

	return (
		<div class="flex flex-row flex-auto mx-4">
			<ScrollArea class="w-1\/3 m-2 p-2 border border-secondary-3">
				<BoundString
					name="text"
					signal={[text, setText as Setter<string | undefined>]}
				/>
				<For each={args()}>
					{(arg, index) => (
						<>
							<div class="flex flex-row items-center justify-center">args[{index()}]</div>
							<div class="relative h-10">
								<TextInput
									class="flex-grow w-full absolute"
									value={arg}
									onInput={(e) => useArgs((a) => (a[index()] = e.currentTarget.value))}
								/>
							</div>
							<Button
								class="mb-4"
								onClick={() => useArgs((a) => a.splice(index(), 1))}
							>
								<span>Remove args[{index()}]</span>
							</Button>
						</>
					)}
				</For>
				<Button
					class="mb-4"
					onClick={() => useArgs((a) => a.push(""))}
				>
					<span>Add args[{args().length}]</span>
				</Button>
			</ScrollArea>
			<div class="w-2\/3 m-2 p-2 border border-secondary-3 flex flex-col justify-center items-center">
				<div class="flex flex-col my-4 items-center">
					<div>L10n.Compose</div>
					<L10n.Compose
						text={text()}
						args={args()}
					/>
					<div class="mt-8">L10n.Stylize</div>
					<L10n.Stylize
						text={text()}
						args={args()}
					/>
				</div>
			</div>
		</div>
	);
};
